import re
from typing import List, Dict, Any


# ----------------------------------------------------------------------
# (Helper functions are assumed to exist in the environment)
# ----------------------------------------------------------------------
# def node_by_title(doc: dict, title: str) -> dict
# def node_by_id(doc: dict, node_id: int | str) -> dict
# def children(doc: dict, node: dict) -> List[dict]
# def table_rows(node: dict) -> List[tuple[int, dict]]   # (row_index, row_dict)
# ----------------------------------------------------------------------


# ----------------------------------------------------------------------
# Internal conveniences
# ----------------------------------------------------------------------
def _find_table(doc: dict, scope: str, suffix: str) -> dict:
    """Return the node whose title ends with suffix under the given scope."""
    scope_node = node_by_title(doc, scope)
    for child_id in scope_node.get("children", []):
        child = node_by_id(doc, child_id)
        if child.get("kind") == "table" and child.get("title", "").endswith(suffix):
            return child
    raise ValueError(f"Table with suffix '{suffix}' not found in scope '{scope}'")


def _find_list(doc: dict, scope: str, suffix: str) -> dict | None:
    """Return the node whose title ends with suffix under the given scope."""
    scope_node = node_by_title(doc, scope)
    for child_id in scope_node.get("children", []):
        child = node_by_id(doc, child_id)
        if child.get("kind") == "list" and child.get("title", "").endswith(suffix):
            return child
    return None


# ----------------------------------------------------------------------
# Public API
# ----------------------------------------------------------------------
def entities(doc: dict, scope: str) -> List[Dict[str, Any]]:
    """Return a list of product entities described in the scope."""
    prod_node = _find_table(doc, scope, ": Products")
    rows = table_rows(prod_node)

    res: List[Dict[str, Any]] = []
    for ridx, row in rows:
        code = row["product"]
        group = row["group"]
        sub = row["sub-group"]
        loc = row["storage location"]
        descr = f"product {code} ({group}-{sub}) in {loc}"
        res.append({"id": code, "description": descr})
    return res


def recorded_end(doc: dict, scope: str) -> float | None:
    """Last day number covered in the ledger of the scope."""
    led_node = _find_table(doc, scope, ": Daily ledger")
    rows = table_rows(led_node)

    last_day = None
    for _, row in rows:
        try:
            d = int(row["day"])
            if last_day is None or d > last_day:
                last_day = d
        except Exception:
            continue
    return float(last_day) if last_day is not None else None


def inputs(doc: dict, scope: str) -> List[Dict[str, Any]]:
    """All external inputs for the process."""
    prod_node = _find_table(doc, scope, ": Products")
    prod_rows = table_rows(prod_node)

    # Map product code to its row index & info
    prod_info: Dict[str, tuple[int, dict]] = {}
    for ridx, row in prod_rows:
        prod_info[row["product"]] = (ridx, row)

    led_node = _find_table(doc, scope, ": Daily ledger")
    led_rows = table_rows(led_node)

    inp: List[Dict[str, Any]] = []

    # Opening stock (time 0)
    for code, (ridx, row) in prod_info.items():
        val = row.get("opening stock", "")
        if val == "":
            continue
        try:
            opening = int(val)
        except Exception:
            continue
        inp.append(
            {
                "id": f"{code}_open_stock",
                "time": 0.0,
                "kind": "opening stock",
                "entities": [code],
                "fields": {"opening_stock": opening},
                "src": [[prod_node["node_id"], ridx, ["opening stock"]]],
            }
        )

    # Production arrivals & sales orders (time = day)
    for ridx, row in led_rows:
        try:
            day = int(row["day"])
        except Exception:
            continue
        code = row["product"]

        prod_val = row.get("produced", "")
        if prod_val not in ("", None):
            try:
                prod_qty = int(prod_val)
            except Exception:
                prod_qty = None
            if prod_qty is not None and prod_qty > 0:
                inp.append(
                    {
                        "id": f"{code}_prod_{day}",
                        "time": float(day),
                        "kind": "production arrival",
                        "entities": [code],
                        "fields": {"produced": prod_qty},
                        "src": [[led_node["node_id"], ridx, ["produced"]]],
                    }
                )
        order_val = row.get("ordered", "")
        if order_val not in ("", None):
            try:
                order_qty = int(order_val)
            except Exception:
                order_qty = None
            if order_qty is not None and order_qty > 0:
                inp.append(
                    {
                        "id": f"{code}_order_{day}",
                        "time": float(day),
                        "kind": "sales order",
                        "entities": [code],
                        "fields": {"ordered": order_qty},
                        "src": [[led_node["node_id"], ridx, ["ordered"]]],
                    }
                )

    return inp


def outcomes(doc: dict, scope: str) -> List[Dict[str, Any]]:
    """All outcomes produced by the process."""
    led_node = _find_table(doc, scope, ": Daily ledger")
    led_rows = table_rows(led_node)

    events_node = _find_list(doc, scope, ": Events")
    events_lines = events_node.get("lines", []) if events_node else []

    out: List[Dict[str, Any]] = []

    # Ledger outcomes
    for ridx, row in led_rows:
        try:
            day = int(row["day"])
        except Exception:
            continue
        code = row["product"]

        # Shipped
        sh_val = row.get("shipped", "")
        if sh_val not in ("", None):
            try:
                shipped = int(sh_val)
            except Exception:
                shipped = None
            if shipped is not None:
                out.append(
                    {
                        "time": float(day),
                        "kind": "shipped",
                        "entities": [code],
                        "value": shipped,
                        "src": [[led_node["node_id"], ridx, ["shipped"]]],
                    }
                )

        # Backordered
        bak_val = row.get("backordered", "")
        if bak_val not in ("", None):
            try:
                backordered = int(bak_val)
            except Exception:
                backordered = None
            if backordered is not None:
                out.append(
                    {
                        "time": float(day),
                        "kind": "backordered",
                        "entities": [code],
                        "value": backordered,
                        "src": [[led_node["node_id"], ridx, ["backordered"]]],
                    }
                )

        # Stock
        stk_val = row.get("stock", "")
        if stk_val not in ("", None):
            try:
                stock = int(stk_val)
            except Exception:
                stock = None
            if stock is not None:
                out.append(
                    {
                        "time": float(day),
                        "kind": "stock",
                        "entities": [code],
                        "value": stock,
                        "src": [[led_node["node_id"], ridx, ["stock"]]],
                    }
                )

    # Event outcomes
    for lineno, line in enumerate(events_lines):
        if line.strip() == "":
            continue
        m_day = re.search(r"Day\s+(\d+)", line)
        if not m_day:
            continue
        day = float(m_day.group(1))

        # Capacity reached
        if "dispatch capacity reached" in line:
            out.append(
                {
                    "time": day,
                    "kind": "capacity reached",
                    "entities": [],
                    "value": None,
                    "src": [[events_node["node_id"], lineno]],
                }
            )
            continue

        # Runs out of stock
        m_run = re.search(r"([A-Z0-9]+)\s+runs out of stock", line)
        if m_run:
            prod_code = m_run.group(1)
            back_num = None
            m_back = re.search(r"\((\d+)\s+units backordered\)", line)
            if m_back:
                back_num = int(m_back.group(1))
            out.append(
                {
                    "time": day,
                    "kind": "runs out of stock",
                    "entities": [prod_code],
                    "value": back_num,
                    "src": [[events_node["node_id"], lineno]],
                }
            )
            continue

        # Order fully backordered
        m_fback = re.search(r"order fully backordered", line)
        if m_fback:
            m_prod = re.search(r"([A-Z0-9]+)\s+order fully backordered", line)
            if m_prod:
                prod_code = m_prod.group(1)
                out.append(
                    {
                        "time": day,
                        "kind": "order fully backordered",
                        "entities": [prod_code],
                        "value": None,
                        "src": [[events_node["node_id"], lineno]],
                    }
                )
            continue

        # Backlog cleared
        m_clear = re.search(r"backlog cleared", line)
        if m_clear:
            m_prod = re.search(r"([A-Z0-9]+)\s+backlog cleared", line)
            if m_prod:
                prod_code = m_prod.group(1)
                out.append(
                    {
                        "time": day,
                        "kind": "backlog cleared",
                        "entities": [prod_code],
                        "value": None,
                        "src": [[events_node["node_id"], lineno]],
                    }
                )
            continue

    return out


def params(doc: dict, scope: str) -> Dict[str, Any]:
    """Return constants defined in scope."""
    scope_node = node_by_title(doc, scope)
    txt = scope_node.get("text", "")
    m = re.search(r"Daily dispatch capacity:\s+(\d+)\s*kg", txt)
    if m:
        return {"dispatch_capacity_kg": int(m.group(1))}
    return {}
